begin;

update public.spell_catalog s set
  name_ru=v.name_ru,
  effect_summary=v.effect_summary,
  author_description=v.author_description,
  author_comment=v.author_comment,
  upcast=v.upcast,
  notes=v.notes
from (values
('booming-blade','Громовой клинок','В рамках сотворения совершаешь рукопашную атаку оружием по существу в пределах 5 футов. При попадании действуют обычные эффекты атаки, а цель до начала твоего следующего хода окружена гулкой энергией; если она добровольно переместится хотя бы на 5 футов, получает 1к8 урона звуком.','Ты бьёшь оружием и оставляешь на цели магическое предупреждение: стой спокойно — или грянет. Особенно приятно против тех, кто очень любит бегать по полю боя.','Заклинание буквально превращает «не двигайся» из просьбы в условие безопасности.','На 5 уровне атака дополнительно наносит 1к8 звуком, а урон за движение становится 2к8. На 11 уровне — 2к8 и 3к8; на 17 — 3к8 и 4к8.','Для сотворения нужна рукопашная атака оружием; урон за движение срабатывает только при добровольном перемещении цели.'),
('control-flames','Контроль пламени','Воздействуешь на немагическое пламя, помещающееся в куб 5 футов: можешь мгновенно погасить его, распространить на соседний источник топлива, изменить яркость света или придать огню простой цвет и форму. Длительные изменения сохраняются до 1 часа.','Небольшая бытовая власть над огнём: погасить костёр, раздуть его, сделать тусклее или заставить изображать дракона. Боевого урона почти нет, зато возможностей для сцены — масса.','Редкий случай, когда спор с костром действительно можно выиграть.','Не усиливается с уровнем.','Одновременно могут действовать до трёх немгновенных эффектов этого заклинания.'),
('create-bonfire','Сотворение костра','Создаёшь костёр в кубе 5 футов на земле в пределах дистанции. Существо в этой области при появлении костра и каждый раз, когда заканчивает там ход, совершает спасбросок Ловкости; при провале получает 1к8 огненного урона. Требуется концентрация до 1 минуты.','Костёр, который не требует дров и очень не любит, когда в нём стоят. Хорош для узких проходов, дверей и других мест, где врагу приходится выбирать между огнём и неудобным маршрутом.','Походный костёр, которому зачем-то выдали спасбросок Ловкости.','Урон становится 2к8 на 5 уровне, 3к8 на 11 и 4к8 на 17.','Область занимает куб 5 футов; повторный урон проверяется при окончании хода существа в костре.'),
('encode-thoughts','Кодирование мыслей','Извлекаешь из своего разума воспоминание, идею или сообщение и превращаешь его в маленькую светящуюся нить мысли, существующую до 8 часов. Нить можно держать и переносить; сотворив заклинание, пока держишь такую нить, ты мгновенно воспринимаешь её содержимое.','Ты буквально вынимаешь мысль из головы и делаешь из неё переносимый магический файл. Если уже читаешь или меняешь чужие мысли другой магией, можно записать и найденную там информацию.','Флешка без USB, зато её невозможно забыть дома — пока не забудешь саму нить.','Не усиливается с уровнем.','Повторное сотворение прекращает существование предыдущей созданной тобой нити. Само заклинание не даёт читать мысли без подходящей магии или способности.'),
('frostbite','Обморожение','Одно существо в пределах дистанции совершает спасбросок Телосложения. При провале оно получает 1к6 урона холодом и совершает с помехой следующую атаку оружием до конца своего следующего хода.','Мороз не только кусает, но и заставляет руки дрожать. Урон небольшой, зато неприятный штраф на следующую оружейную атаку часто важнее самого к6.','Хороший способ объяснить противнику, что перчатки всё-таки были нужны.','Урон становится 2к6 на 5 уровне, 3к6 на 11 и 4к6 на 17.','Помеха относится только к следующей атаке оружием и исчезает не позднее конца следующего хода цели.'),
('green-flame-blade','Клинок зелёного пламени','В рамках сотворения совершаешь рукопашную атаку оружием по существу в пределах 5 футов. При попадании действуют обычные эффекты атаки, а зелёное пламя перескакивает на другое существо по твоему выбору в 5 футах от первой цели и наносит ему огненный урон, равный модификатору твоей заклинательной характеристики.','Обычный удар оружием, после которого огонь решает, что одной жертвы недостаточно. Особенно полезен, когда два противника уверены, что стоять рядом — хорошая идея.','Магия, наглядно объясняющая понятие «не кучкуйтесь».','На 5 уровне первая цель дополнительно получает 1к8 огнём, а вторая — 1к8 + модификатор. На 11 уровне — 2к8 и 2к8 + модификатор; на 17 — 3к8 и 3к8 + модификатор.','Для прыжка пламени нужна вторая цель в пределах 5 футов от основной.'),
('gust','Порыв','Создаёшь короткий порыв ветра. Можно заставить Среднее или меньшее существо пройти спасбросок Силы и при провале оттолкнуть его на 5 футов; переместить незакреплённый предмет весом до 5 фунтов на расстояние до 10 футов; либо создать безвредный воздушный эффект.','Маленький телекинез для тех, кто предпочитает ветер: толкнуть человека, смахнуть предмет со стола или эффектно распахнуть плащ перед входом.','Урона нет, зато драматичности — сколько унесёт ветром.','Не усиливается с уровнем.','Толчок работает только по существам Среднего размера или меньше; направление — от тебя.'),
('infestation','Заражение','Одно существо совершает спасбросок Телосложения. При провале получает 1к6 урона ядом, после чего, если может двигаться, перемещается на 5 футов в случайном горизонтальном направлении. Это вынужденное движение не провоцирует атаки.','Ты на мгновение устраиваешь цели очень личный апокалипсис из паразитов. Вред небольшой, зато противник может внезапно оказаться на соседней клетке совсем не по своему плану.','Пять футов панического «снимите это с меня» иногда ценнее целого огненного шара.','Урон становится 2к6 на 5 уровне, 3к6 на 11 и 4к6 на 17.','Если выпавшее направление заблокировано, цель остаётся на месте. Перемещение не вызывает провоцированных атак.'),
('lightning-lure','Лассо молнии','Одно существо в пределах 15 футов совершает спасбросок Силы. При провале ты подтягиваешь его к себе на расстояние до 10 футов; если после этого оно оказывается в пределах 5 футов от тебя, получает 1к8 урона электричеством.','Электрический крюк: сначала притяни проблему к себе, потом вспомни, что проблема теперь действительно рядом. Отлично работает, когда рядом с тобой стоят союзники, которым это нравится больше.','Название «лассо» честно предупреждает: дальняя дистанция быстро перестаёт быть дальней.','Урон становится 2к8 на 5 уровне, 3к8 на 11 и 4к8 на 17.','Урон наносится только если после притягивания цель находится в пределах 5 футов от тебя.'),
('magic-stone','Волшебный камень','Бонусным действием зачаровываешь от одного до трёх камешков. Зачарованным камнем можно совершить дальнобойную атаку заклинанием, бросив его или выпустив из пращи; при попадании он наносит 1к6 + модификатор твоей заклинательной характеристики дробящего урона.','Берёшь обычный камень и повышаешь его квалификацию до магического боеприпаса. Камни можно раздать союзникам — для атаки они используют твою магическую силу, а не свою меткость.','Великая друидская традиция: если магия закончилась, всё ещё остаётся камень.','Не усиливается с уровнем персонажа.','Можно зачаровать до трёх камней за одно бонусное действие. Повторное сотворение прекращает магию на ранее зачарованных камнях.')
) as v(slug,name_ru,effect_summary,author_description,author_comment,upcast,notes)
where s.slug=v.slug and s.source_kind='official';

update public.spell_catalog s set
  name_ru=v.name_ru,
  effect_summary=v.effect_summary,
  author_description=v.author_description,
  author_comment=v.author_comment,
  upcast=v.upcast,
  notes=v.notes
from (values
('mind-sliver','Осколок разума','Одно существо в пределах дистанции совершает спасбросок Интеллекта. При провале оно получает 1к6 психического урона и вычитает 1к4 из следующего спасброска, который совершит до конца твоего следующего хода.','Крошечный ментальный укол, который не столько убивает, сколько портит следующий важный момент цели. Особенно приятно перед заклинанием союзника со спасброском.','Небольшой урон, большая перспектива сделать чужой следующий бросок заметно хуже.','Урон становится 2к6 на 5 уровне, 3к6 на 11 и 4к6 на 17.','Штраф 1к4 применяется только к следующему спасброску и после этого исчезает.'),
('mold-earth','Формование земли','Воздействуешь на куб рыхлой земли размером до 5 футов: можешь мгновенно выкопать её и переместить по земле на расстояние до 5 футов, оставить рисунок или цвет до 1 часа либо сделать участок труднопроходимым или обычным до 1 часа.','Маленькая землеройная магия для окопов, надписей, следов и очень быстрого ландшафтного дизайна. В бою редко убивает, зато вне боя постоянно находит работу.','Лопата наконец проиграла конкуренцию заговору.','Не усиливается с уровнем.','Одновременно могут действовать не более двух немгновенных эффектов этого заклинания.'),
('primal-savagery','Первобытная ярость','Твои зубы или ногти на мгновение превращаются в едкое природное оружие. Соверши рукопашную атаку заклинанием по существу в пределах 5 футов; при попадании цель получает 1к10 урона кислотой.','На секунду друид перестаёт притворяться мирным любителем природы и просто отращивает что-нибудь крайне неприятное. Никакого оружия — только ты, цель и плохое решение подойти ближе.','Иногда связь с природой выражается не цветами, а кислотными когтями.','Урон становится 2к10 на 5 уровне, 3к10 на 11 и 4к10 на 17.','Это рукопашная атака заклинанием, а не атака естественным или обычным оружием.'),
('sapping-sting','Истощающий укол','Одно видимое существо в пределах дистанции совершает спасбросок Телосложения. При провале оно получает 1к4 некротического урона и падает ничком.','Урона почти символически мало, зато возможность уронить противника с расстояния иногда превращает этот к4 в очень выгодную инвестицию для всей группы.','Главная часть заклинания — не «1к4», а звук падающего врага.','Урон становится 2к4 на 5 уровне, 3к4 на 11 и 4к4 на 17.','При успешном спасброске цель не получает урон и не падает ничком.'),
('shape-water','Формование воды','Воздействуешь на воду в кубе до 5 футов. Можно переместить её или изменить течение до 5 футов, придать простые формы и движение на 1 час, изменить цвет или прозрачность на 1 час либо заморозить воду на 1 час, если в ней нет существ.','Универсальный водяной конструктор: перелить, заморозить, покрасить, заставить двигаться. Боевой урон отсутствует, зато творческое применение ограничено в основном наличием воды и совестью мастера.','Если рядом есть бочка воды, у друида внезапно появляется проект.','Не усиливается с уровнем.','Одновременно могут действовать до двух немгновенных эффектов. Само изменение не наносит урон.'),
('sword-burst','Вспышка мечей','Все существа по твоему выбору в пределах 5 футов совершают спасбросок Ловкости. При провале цель получает 1к6 урона силовым полем от возникших вокруг тебя призрачных клинков.','Когда окружающих стало слишком много, магия предлагает простое решение: на мгновение окружить себя лезвиями из чистой силы.','Очень убедительный аргумент против плотного окружения волшебника.','Урон становится 2к6 на 5 уровне, 3к6 на 11 и 4к6 на 17.','Ты выбираешь, какие существа в зоне должны совершать спасбросок.'),
('thunderclap','Раскат грома','Все существа по твоему выбору в пределах 5 футов совершают спасбросок Телосложения. При провале получают 1к6 урона звуком. Раскат слышен на расстоянии до 100 футов.','Ты создаёшь очень локальную грозу и одновременно сообщаешь всему подземелью, что группа находится примерно здесь.','Скрытность заканчивается ровно там, где начинается «раскат грома».','Урон становится 2к6 на 5 уровне, 3к6 на 11 и 4к6 на 17.','Звук заклинания слышен примерно за 100 футов, что может иметь последствия вне боя.'),
('toll-the-dead','Погребальный звон','Одно видимое существо в пределах дистанции совершает спасбросок Мудрости. При провале получает 1к8 некротического урона; если у цели уже не хватает хотя бы одного хита, вместо этого наносится 1к12.','Магический колокол особенно убедительно звучит для тех, кого уже успели ранить. По свежей цели — неприятно, по потрёпанной — значительно неприятнее.','Заклинание буквально проверяет: «тебя уже били?» — и радуется положительному ответу.','Кости урона становятся двумя на 5 уровне, тремя на 11 и четырьмя на 17: 2к8/2к12, 3к8/3к12, 4к8/4к12.','Размер кости определяется состоянием цели в момент нанесения урона: если у неё не полные хиты, используется к12.'),
('word-of-radiance','Слово сияния','Все выбранные тобой существа, которых ты видишь в пределах 5 футов, совершают спасбросок Телосложения. При провале получают 1к6 урона излучением.','Короткое священное слово, после которого рядом с жрецом становится слишком ярко и слишком больно для всех, кого он не включил в список друзей.','Божественное «разойдитесь» с очень убедительным световым сопровождением.','Урон становится 2к6 на 5 уровне, 3к6 на 11 и 4к6 на 17.','Ты сам выбираешь существ в зоне, поэтому союзников можно не задевать.')
) as v(slug,name_ru,effect_summary,author_description,author_comment,upcast,notes)
where s.slug=v.slug and s.source_kind='official';

commit;
